package nrqlmacros

import "encoding/json"

// This file contains the single item that tutone does not generate for the nrqlmacros
// package: the UnmarshalJSON for EntityManagementActorStitchedFields.
//
// All input types (EntityManagementNRQLMacroEntityCreateInput, UpdateInput) and result
// types (CreateResult, UpdateResult) are now generated by tutone via explicit entries in
// the .tutone.yml types block combined with --refetch. Those types were absent from the
// general schema introspection dump but are reachable when queried by name.
//
// The UnmarshalJSON below is needed because the Entity field on
// EntityManagementActorStitchedFields is an interface; Go's default JSON decoder cannot
// dispatch it without knowing the concrete type at decode time. Tutone generates this
// function in pkg/pipelinecontrol ("// DO NOT DELETE") but omits it in packages where
// include_implementations restricts the interface to a single concrete type. Without it
// GetEntity always returns a JSON decode error.
//
// Regenerating pkg/nrqlmacros should leave this file intact.
func (x *EntityManagementActorStitchedFields) UnmarshalJSON(b []byte) error {
	var objMap map[string]*json.RawMessage
	if err := json.Unmarshal(b, &objMap); err != nil {
		return err
	}

	for k, v := range objMap {
		if v == nil {
			continue
		}
		switch k {
		case "entity":
			xxx, err := UnmarshalEntityManagementEntityInterface(*v)
			if err != nil {
				return err
			}
			if xxx != nil {
				x.Entity = *xxx
			}
		case "entitySearch":
			if err := json.Unmarshal(*v, &x.EntitySearch); err != nil {
				return err
			}
		}
	}
	return nil
}
